const BrowserRouter = require("react-router-dom")
const Routes = require("react-router-dom")
const Route = require("react-router-dom")

import Members from "pages/Members"

function App() {
  return (
    <div className="App">

        <BrowserRouter>
          <Routes>
            <Route path="/" element={<Members/>}/>
          </Routes>
        </BrowserRouter>
    </div>

  )
}

export default App;
